// Template set 5. See card/templates/README.md.
// Creative trades (designer, film, apps, music, weddings, DJ, NGO) and style-led designs (luxury, playful, Hindi, Marathi).
// All artwork is generated by the functions below. Sample details are invented.
import { ellipsePath, rectPath } from '../src/core/pathutil.js';
import { A, B, E, H, L, LOGO, QR, R, T, W } from './kit.js';

const PHONE = '+91 98765 43210';

const f = (v) => String(Math.round(v * 100) / 100);

const circle = (cx, cy, r) => ellipsePath(cx, cy, r, r);
const rad = (deg) => (deg * Math.PI) / 180;

/** Repeatable random numbers, so the art is identical on every render. */
function seeded(seed) {
  let s = seed;
  return () => {
    s = (s * 1664525 + 1013904223) % 4294967296;
    return s / 4294967296;
  };
}

/* ---------- Off Register ---------- */

const quarter = (cx, cy, r, a0) => {
  const p = (a) => `${f(cx + Math.cos(rad(a)) * r)} ${f(cy + Math.sin(rad(a)) * r)}`;
  return `M${f(cx)} ${f(cy)}L${p(a0)}A${f(r)} ${f(r)} 0 0 1 ${p(a0 + 90)}Z`;
};

/** One printing plate of a registration target: two opposite quarters of a disc. */
function targetPlate(cx, cy, r, a0) {
  return quarter(cx, cy, r, a0) + quarter(cx, cy, r, a0 + 180);
}

function targetLines(cx, cy, r) {
  const o = r + 1.6;
  return `${circle(cx, cy, r)}M${f(cx - o)} ${f(cy)}H${f(cx + o)}M${f(cx)} ${f(cy - o)}V${f(cy + o)}`;
}

/** Printer's crop marks, sitting in the outer 3 mm as if this card were still on the press sheet. */
function cropMarks(w, h, inset = 3.2, reach = 2.4) {
  const seg = (x, y, dx, dy) => `M${f(x)} ${f(y)}l${f(dx)} ${f(dy)}`;
  return [
    seg(0, inset, reach, 0),
    seg(inset, 0, 0, reach),
    seg(w, inset, -reach, 0),
    seg(w - inset, 0, 0, reach),
    seg(0, h - inset, reach, 0),
    seg(inset, h, 0, -reach),
    seg(w, h - inset, -reach, 0),
    seg(w - inset, h, 0, -reach),
  ].join('');
}

/** One chip of a swatch fan, pivoting on (px, py). */
function fanChip(px, py, r0, r1, wid, deg) {
  const a = rad(deg);
  const ux = Math.cos(a);
  const uy = Math.sin(a);
  const pt = (r, o) => `${f(px + ux * r - uy * o)} ${f(py + uy * r + ux * o)}`;
  return `M${pt(r0, -wid / 2)}L${pt(r1, -wid / 2)}L${pt(r1, wid / 2)}L${pt(r0, wid / 2)}Z`;
}

/* ---------- Film Strip ---------- */

function sprockets(w, h) {
  let d = '';
  for (let y = -2.4; y < h + 3; y += 4.6) {
    d += rectPath(1, y, 2.4, 3, 0.5) + rectPath(w - 3.4, y, 2.4, 3, 0.5);
  }
  return d;
}

const boat = (x, y, s) =>
  `M${f(x - 3 * s)} ${f(y)}H${f(x + 3 * s)}L${f(x + 2.1 * s)} ${f(y + 1.1 * s)}H${f(x - 2.1 * s)}Z` +
  `M${f(x - 0.2 * s)} ${f(y - 0.2 * s)}V${f(y - 4 * s)}L${f(x + 2.2 * s)} ${f(y - 0.2 * s)}Z`;

/** The sea with its rounded lower corners, flush with the frame. */
const seaPath = (x, y, w, h, r = 0.7) =>
  `M${f(x)} ${f(y)}H${f(x + w)}V${f(y + h - r)}Q${f(x + w)} ${f(y + h)} ${f(x + w - r)} ${f(y + h)}H${f(x + r)}Q${f(x)} ${f(y + h)} ${f(x)} ${f(y + h - r)}Z`;

/* ---------- Profile Screen ---------- */

function statusIcons(x, y) {
  let d = '';
  for (let i = 0; i < 4; i++) d += rectPath(x + i * 1.05, y + 1.8 - i * 0.55, 0.72, 0.6 + i * 0.55, 0.15);
  return d;
}

/* ---------- Stave ---------- */

const STAVE_GAP = 4.1;
const STAVE_X = 55.6;
const STAVE_Y = [19, 23.1, 27.2, 31.3, 35.4];
const staveCurve = (i) => {
  const y = STAVE_Y[i];
  const end = -11 + i * 9;
  return [
    [STAVE_X + 9, y],
    [STAVE_X + 20, y],
    [STAVE_X + 25, end + 13],
    [93, end],
  ];
};

function bez(c, t) {
  const m = 1 - t;
  const k = [m * m * m, 3 * m * m * t, 3 * m * t * t, t * t * t];
  return [k.reduce((s, v, i) => s + v * c[i][0], 0), k.reduce((s, v, i) => s + v * c[i][1], 0)];
}

function staveLines() {
  let d = `M${f(STAVE_X)} ${f(STAVE_Y[0])}V${f(STAVE_Y[4])}`;
  for (let i = 0; i < 5; i++) {
    const c = staveCurve(i);
    d += `M${f(STAVE_X)} ${f(STAVE_Y[i])}L${f(c[0][0])} ${f(c[0][1])}C${f(c[1][0])} ${f(c[1][1])} ${f(c[2][0])} ${f(c[2][1])} ${f(c[3][0])} ${f(c[3][1])}`;
  }
  return d;
}

/** A tilted note head as a closed curve. */
function noteHead(cx, cy, s) {
  const a = rad(-22);
  const ca = Math.cos(a);
  const sa = Math.sin(a);
  const rx = 1.28 * s;
  const ry = 0.9 * s;
  const k = 0.5523;
  const p = (x, y) => `${f(cx + x * ca - y * sa)} ${f(cy + x * sa + y * ca)}`;
  return (
    `M${p(rx, 0)}C${p(rx, ry * k)} ${p(rx * k, ry)} ${p(0, ry)}C${p(-rx * k, ry)} ${p(-rx, ry * k)} ${p(-rx, 0)}` +
    `C${p(-rx, -ry * k)} ${p(-rx * k, -ry)} ${p(0, -ry)}C${p(rx * k, -ry)} ${p(rx, -ry * k)} ${p(rx, 0)}Z`
  );
}

const stem = (cx, cy, s, len = 7.4) => rectPath(cx + 1.02 * s, cy - len * s, 0.36 * s, len * s, 0);

/** Notes riding on the rising stave: single quavers and beamed pairs, getting bigger as they lift off. */
function staveNotes() {
  let d = '';
  const on = (line, t) => bez(staveCurve(line), t);
  const single = (line, t, s) => {
    const [x, y] = on(line, t);
    d += noteHead(x, y, s) + stem(x, y, s);
    const tx = x + 1.2 * s;
    const ty = y - 7.4 * s;
    d += `M${f(tx)} ${f(ty)}C${f(tx + 0.3 * s)} ${f(ty + 2 * s)} ${f(tx + 3 * s)} ${f(ty + 2.6 * s)} ${f(tx + 2 * s)} ${f(ty + 5.4 * s)}C${f(tx + 2.2 * s)} ${f(ty + 3.6 * s)} ${f(tx + 0.8 * s)} ${f(ty + 3.2 * s)} ${f(tx)} ${f(ty + 2.6 * s)}Z`;
  };
  const pair = (l1, t1, l2, t2, s) => {
    const [x1, y1] = on(l1, t1);
    const [x2, y2] = on(l2, t2);
    d += noteHead(x1, y1, s) + noteHead(x2, y2, s) + stem(x1, y1, s, 6.6) + stem(x2, y2, s, 6.6);
    const ax = x1 + 1.02 * s;
    const ay = y1 - 6.6 * s;
    const bx = x2 + 1.38 * s;
    const by = y2 - 6.6 * s;
    d += `M${f(ax)} ${f(ay)}L${f(bx)} ${f(by)}L${f(bx)} ${f(by + 1 * s)}L${f(ax)} ${f(ay + 1 * s)}Z`;
  };
  single(4, 0.08, 0.85);
  pair(3, 0.3, 2, 0.44, 0.95);
  single(1, 0.6, 1.05);
  pair(3, 0.72, 2, 0.84, 1.1);
  return d;
}

/** A treble clef drawn as a single line, in staff-space units. */
function trebleClef(x, y0, s) {
  const p = (a, b) => `${f(x + a * s)} ${f(y0 + b * s)}`;
  return (
    `M${p(0.35, 3.45)}C${p(-0.25, 3.7)} ${p(-0.75, 3.0)} ${p(-0.15, 2.55)}` +
    `C${p(0.5, 2.1)} ${p(1.3, 2.55)} ${p(1.25, 3.3)}C${p(1.2, 4.2)} ${p(0.2, 4.55)} ${p(-0.55, 4.2)}` +
    `C${p(-1.55, 3.7)} ${p(-1.5, 2.65)} ${p(-0.8, 1.85)}C${p(-0.2, 1.15)} ${p(0.62, 0.55)} ${p(0.55, -0.5)}` +
    `C${p(0.5, -1.15)} ${p(0.2, -1.55)} ${p(0.02, -1.5)}C${p(-0.4, -1.4)} ${p(-0.58, -0.75)} ${p(-0.45, -0.1)}` +
    `L${p(0.42, 5.1)}C${p(0.5, 5.75)} ${p(0.05, 6.1)} ${p(-0.4, 6)}C${p(-0.85, 5.9)} ${p(-0.9, 5.3)} ${p(-0.42, 5.25)}`
  );
}

const SWARAS = ['सा', 'रे', 'ग', 'म', 'प', 'ध', 'नि', 'सां'];

/* ---------- Marigold ---------- */

/** A ruffled flower as one closed scalloped curve. */
function ruffle(cx, cy, r, lobes, phase = 0) {
  const pt = (a, rr) => `${f(cx + Math.cos(a) * rr)} ${f(cy + Math.sin(a) * rr)}`;
  const step = (Math.PI * 2) / lobes;
  let d = `M${pt(phase, r * 0.8)}`;
  for (let i = 0; i < lobes; i++) {
    const a = phase + i * step;
    d += `Q${pt(a + step / 2, r * 1.28)} ${pt(a + step, r * 0.8)}`;
  }
  return `${d}Z`;
}

const leafDrop = (x, y, len, wid) =>
  `M${f(x)} ${f(y)}C${f(x + wid)} ${f(y + len * 0.3)} ${f(x + wid * 0.7)} ${f(y + len * 0.75)} ${f(x)} ${f(y + len)}C${f(x - wid * 0.7)} ${f(y + len * 0.75)} ${f(x - wid)} ${f(y + len * 0.3)} ${f(x)} ${f(y)}Z`;

/** Strings of marigolds hanging from the top edge. Each entry is [x, flowers]. */
function garland(strands, { r = 2.3, pitch = 4.35, top = -1.5 } = {}) {
  const out = { thread: '', outerA: '', outerB: '', innerA: '', innerB: '', eyes: '', leaves: '' };
  strands.forEach(([x, n], si) => {
    const end = top + n * pitch;
    out.thread += `M${f(x)} -3V${f(end)}`;
    for (let i = 0; i < n; i++) {
      const y = top + i * pitch;
      const first = (i + si) % 2 === 0;
      const ph = (i * 0.7 + si) % 1.2;
      if (first) {
        out.outerA += ruffle(x, y, r, 9, ph);
        out.innerB += ruffle(x, y, r * 0.58, 6, ph + 0.3);
      } else {
        out.outerB += ruffle(x, y, r, 9, ph);
        out.innerA += ruffle(x, y, r * 0.58, 6, ph + 0.3);
      }
      out.eyes += `M${f(x)} ${f(y)}h0.01`;
    }
    out.leaves += leafDrop(x, end - 1.6, 4.2, 1.2);
  });
  return out;
}

const garlandEls = (prefix, g) => [
  A(`${prefix}thread`, g.thread, { stroke: '$thread', sw: 0.2 }),
  A(`${prefix}leaf`, g.leaves, { fill: '$leaf' }),
  A(`${prefix}oa`, g.outerA, { fill: '$petalA' }),
  A(`${prefix}ob`, g.outerB, { fill: '$petalB' }),
  A(`${prefix}ia`, g.innerA, { fill: '$petalA' }),
  A(`${prefix}ib`, g.innerB, { fill: '$petalB' }),
  A(`${prefix}eye`, g.eyes, { stroke: '$eye', sw: 0.75, cap: 'round' }),
];

/* ---------- Mix Desk ---------- */

function faderSlots(xs, y, h) {
  let slots = '';
  let ticks = '';
  for (const x of xs) {
    slots += rectPath(x - 0.45, y, 0.9, h, 0.45);
    for (let t = 0; t <= 6; t++) ticks += `M${f(x + 1.1)} ${f(y + (t * h) / 6)}h${t % 3 === 0 ? 1 : 0.6}`;
  }
  return { slots, ticks };
}

function knobPointers(xs, y, r, angles) {
  return xs
    .map((x, i) => {
      const a = rad(angles[i % angles.length]);
      return `M${f(x + Math.cos(a) * r * 0.2)} ${f(y + Math.sin(a) * r * 0.2)}L${f(x + Math.cos(a) * r)} ${f(y + Math.sin(a) * r)}`;
    })
    .join('');
}

/** A strip of masking tape with a torn right end. */
function tape(x, y, w, h, seed = 5) {
  const rnd = seeded(seed);
  let d = `M${f(x)} ${f(y)}L${f(x + w)} ${f(y)}`;
  const n = 8;
  for (let i = 1; i <= n; i++) d += `L${f(x + w + (i % 2 ? 0.7 : -0.5) * (0.4 + rnd()))} ${f(y + (i * h) / n)}`;
  return `${d}L${f(x)} ${f(y + h)}Z`;
}

function vinylGrooves(cx, cy, r0, r1) {
  let d = '';
  for (let r = r0; r < r1; r += 1.15) d += circle(cx, cy, r);
  return d;
}

function vinylSheen(cx, cy, r, a0, spread) {
  const p = (a) => `${f(cx + Math.cos(rad(a)) * r)} ${f(cy + Math.sin(rad(a)) * r)}`;
  return `M${f(cx)} ${f(cy)}L${p(a0 - spread)}A${r} ${r} 0 0 1 ${p(a0 + spread)}Z`;
}

/* ---------- Paper Chain ---------- */

