/** A straight chain of dolls, one path per paint. */
function dollChain(x0, footY, s, types, paints) {
  const out = Array(paints).fill('');
  types.forEach((t, i) => {
    const doll = DOLLS[t];
    const cx = x0 + (i + 0.5) * s;
    const pts = doll.body.map(([x, y]) => `${f(cx + x * s)} ${f(footY + y * s)}`);
    out[i % paints] += `M${pts.join('L')}Z${circle(cx, footY + doll.head[0] * s, doll.head[1] * s)}`;
  });
  return out;
}

/** The same dolls in a ring, feet inwards, holding hands around the centre. */
function dollRing(cx, cy, r0, s, types, paints) {
  const out = Array(paints).fill('');
  const n = types.length;
  types.forEach((t, i) => {
    const doll = DOLLS[t];
    const th = (i / n) * Math.PI * 2 - Math.PI / 2;
    const map = (x, y) => {
      const a = th + (x * Math.PI * 2) / n;
      const rr = r0 - y * s;
      return [cx + Math.cos(a) * rr, cy + Math.sin(a) * rr];
    };
    const pts = doll.body.map(([x, y]) => map(x, y).map(f).join(' '));
    const [hx, hy] = map(0, doll.head[0]);
    out[i % paints] += `M${pts.join('L')}Z${circle(hx, hy, doll.head[1] * s)}`;
  });
  return out;
}

/* ---------- Guilloche ---------- */

/** A woven band of sine curves around a centre, as on a banknote. Points outside the bleed are dropped to keep the path small. */
function guilloche(cx, cy, r0, r1, lobes, curves, perLobe, box) {
  const mid = (r0 + r1) / 2;
  const amp = (r1 - r0) / 2;
  const n = lobes * perLobe;
  let d = '';
  for (let k = 0; k < curves; k++) {
    const phase = (k / curves) * Math.PI * 2;
    let pen = false;
    let first = '';
    let whole = true;
    let sub = '';
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      const rr = mid + amp * Math.sin(lobes * a + phase);
      const x = cx + Math.cos(a) * rr;
      const y = cy + Math.sin(a) * rr;
      const inside = x >= box[0] && x <= box[2] && y >= box[1] && y <= box[3];
      if (!inside) {
        pen = false;
        whole = false;
        continue;
      }
      const pt = `${f(x)} ${f(y)}`;
      if (!first) first = pt;
      sub += `${pen ? 'L' : 'M'}${pt}`;
      pen = true;
    }
    d += whole ? `${sub}Z` : sub;
  }
  return d;
}

