/* ---------- Peekaboo ---------- */

const domeTop = (x, top, w, bottom) =>
  `M${f(x)} ${f(bottom)}V${f(top + w / 2)}A${f(w / 2)} ${f(w / 2)} 0 0 1 ${f(x + w)} ${f(top + w / 2)}V${f(bottom)}Z`;

function spikyTop(x, top, w, bottom, n = 4, spike = 3.6) {
  let d = `M${f(x)} ${f(bottom)}V${f(top + spike)}`;
  const s = w / n;
  for (let i = 0; i < n; i++) d += `L${f(x + s * (i + 0.5))} ${f(top)}L${f(x + s * (i + 1))} ${f(top + spike)}`;
  return `${d}V${f(bottom)}Z`;
}

function wavyTop(x, top, w, bottom, n = 3) {
  const s = w / n;
  let d = `M${f(x)} ${f(bottom)}V${f(top + s / 2)}`;
  for (let i = 0; i < n; i++) d += `A${f(s / 2)} ${f(s / 2)} 0 0 1 ${f(x + s * (i + 1))} ${f(top + s / 2)}`;
  return `${d}V${f(bottom)}Z`;
}

/** Googly eyes that all look at one point. Returns [whites, pupils] path data. */
function eyes(list, tx, ty) {
  let white = '';
  let pupil = '';
  for (const [x, y, r] of list) {
    const dx = tx - x;
    const dy = ty - y;
    const len = Math.hypot(dx, dy) || 1;
    const p = r * 0.5;
    white += circle(x, y, r);
    pupil += circle(x + (dx / len) * (r - p) * 0.92, y + (dy / len) * (r - p) * 0.92, p);
  }
  return [white, pupil];
}

/* ---------- Station Board ---------- */

function postBands(x, y0, y1, w) {
  let d = '';
  for (let y = y0; y < y1; y += 4.4) d += rectPath(x, y, w, 2.2);
  return d;
}

/* ---------- Pati (school slate) ---------- */

/** Chalk marks over a word: tiny strokes in the slate's own colour, so the letters look dry and dusty. */
function chalkGrain(x, y, w, h, count, seed) {
  const rnd = seeded(seed);
  let d = '';
  for (let i = 0; i < count; i++) {
    const px = x + rnd() * w;
    const py = y + rnd() * h;
    const len = 0.4 + rnd() * 1.1;
    d += `M${f(px)} ${f(py)}l${f(len)} ${f(-len * 0.22 + rnd() * 0.16)}`;
  }
  return d;
}

/** A hand-drawn line through points: slight wobble, drawn twice like a real chalk stroke. */
function chalkLine(points, seed, wobble = 0.16) {
  const rnd = seeded(seed);
  let d = '';
  for (let pass = 0; pass < 2; pass++) {
    points.forEach(([x, y], i) => {
      d += `${i ? 'L' : 'M'}${f(x + (rnd() - 0.5) * wobble)} ${f(y + (rnd() - 0.5) * wobble)}`;
    });
  }
  return d;
}

const chalkCircle = (cx, cy, rx, ry, seed, turns = 1.08) => {
  const pts = [];
  for (let i = 0; i <= 26; i++) {
    const a = (i / 26) * Math.PI * 2 * turns - 1.2;
    const g = 1 + i * 0.002;
    pts.push([cx + Math.cos(a) * rx * g, cy + Math.sin(a) * ry * g]);
  }
  return chalkLine(pts, seed, 0.14);
};

/** The drawing every child in India makes first: two hills, the sun between them, birds and a river. */
function hillsDoodle(x, y) {
  const P = (a, b) => [x + a, y + b];
  let d = chalkLine([P(0, 13), P(5, 5.4), P(10.4, 13)], 11);
  d += chalkLine([P(8.6, 10.8), P(13.4, 4.6), P(19.6, 13)], 12);
  d += chalkLine([P(0, 13), P(19.6, 13)], 13, 0.2);
  d += chalkCircle(x + 9.2, y + 3.4, 2.1, 2.1, 14);
  [
    [-90, 3.2],
    [-45, 3.2],
    [-135, 3.2],
    [-10, 3.1],
    [-170, 3.1],
  ].forEach(([deg, r0], i) => {
    const a = rad(deg);
    d += chalkLine(
      [P(9.2 + Math.cos(a) * r0, 3.4 + Math.sin(a) * r0), P(9.2 + Math.cos(a) * (r0 + 1.2), 3.4 + Math.sin(a) * (r0 + 1.2))],
      20 + i,
      0.1,
    );
  });
  d += chalkLine([P(15.4, 1.2), P(16.3, 2), P(17.2, 1.2), P(18.1, 2), P(19, 1.2)], 31, 0.1);
  d += chalkLine([P(9.4, 13), P(7.8, 15), P(10.6, 16.6)], 32, 0.14);
  d += chalkLine([P(11.4, 13), P(10.4, 14.7), P(13, 16.6)], 33, 0.14);
  return d;
}

