/**
 * A round logo holder that flows in a stack. Initials always centre in their box, so a bare logo never lines up with the
 * text below it: a badge gives it its own edge, and a pale one keeps an uploaded logo readable. The next member needs `gap + BADGE_PAD * size`.
 */
const BADGE_PAD = 0.14;
const badge = (stack, x, size, disc, ink) => {
  const pad = size * BADGE_PAD;
  return [
    E('badge', x, 0, size, size, disc, { stack }),
    LOGO('logo', x + pad, 0, size - 2 * pad, ink, { stack, gap: pad - size, fallbackSize: size * 1.25 }),
  ];
};

